const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Upper Arrow Lake area (British Columbia, Canada)
  const upperArrowLake = ee.Geometry.Point([-117.8, 50.3]);
  const region = upperArrowLake.buffer(20000); // 20km buffer

  // Define morning (8-10 AM local) and afternoon (2-4 PM local) times
  // Local time is UTC-7 or UTC-8, using UTC-7 for October
  // Morning: 15:00-17:00 UTC, Afternoon: 21:00-23:00 UTC
  const morningStart = ee.Date('2018-10-22T15:00:00');
  const morningEnd = ee.Date('2018-10-22T17:00:00');
  const afternoonStart = ee.Date('2018-10-22T21:00:00');
  const afternoonEnd = ee.Date('2018-10-22T23:00:00');

  // Try GOES-16 (East) - Band 2 (Red visible, 0.64 μm) for fog detection
  let morningCol = ee.ImageCollection('NOAA/GOES/16/MCMIPC')
    .filterBounds(region)
    .filterDate(morningStart, morningEnd)
    .select('CMI_C02');

  let afternoonCol = ee.ImageCollection('NOAA/GOES/16/MCMIPC')
    .filterBounds(region)
    .filterDate(afternoonStart, afternoonEnd)
    .select('CMI_C02');

  const mornSize = await morningCol.size().getInfo();
  const aftSize = await afternoonCol.size().getInfo();

  console.log(`Morning images: ${mornSize}, Afternoon images: ${aftSize}`);

  if (mornSize === 0 || aftSize === 0) {
    // Try GOES-17 (West) which better covers this area
    morningCol = ee.ImageCollection('NOAA/GOES/17/MCMIPF')
      .filterBounds(region)
      .filterDate(morningStart, morningEnd)
      .select('CMI_C02');

    afternoonCol = ee.ImageCollection('NOAA/GOES/17/MCMIPF')
      .filterBounds(region)
      .filterDate(afternoonStart, afternoonEnd)
      .select('CMI_C02');

    const mornSize2 = await morningCol.size().getInfo();
    const aftSize2 = await afternoonCol.size().getInfo();

    console.log(`GOES-17 Morning images: ${mornSize2}, Afternoon images: ${aftSize2}`);

    if (mornSize2 === 0 || aftSize2 === 0) {
      console.log("No GOES data available for specified times");
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Get median composite for each time period
  const morningImg = morningCol.median();
  const afternoonImg = afternoonCol.median();

  // Low reflectance in visible band indicates fog/low clouds
  // Fog typically has reflectance < 0.3-0.4
  const fogThreshold = 0.35;
  const morningFog = morningImg.lt(fogThreshold);
  const afternoonFog = afternoonImg.lt(fogThreshold);

  // Calculate fog coverage area
  const pixelArea = ee.Image.pixelArea();

  const morningStats = await morningFog.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).getInfo();

  const afternoonStats = await afternoonFog.multiply(pixelArea).reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).getInfo();

  const morningCount = await morningFog.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 2000,
    maxPixels: 1e9
  }).getInfo();

  const morningArea = morningStats.CMI_C02;
  const afternoonArea = afternoonStats.CMI_C02;
  const totalPixels = morningCount.CMI_C02;

  console.log(`Total pixels analyzed: ${totalPixels}`);

  if (totalPixels === 0) {
    console.log("No valid pixels in region");
    console.log("<answer>C2</answer>");
    return;
  }

  if (morningArea === null || morningArea === undefined || 
      afternoonArea === null || afternoonArea === undefined) {
    console.log("Calculation failed - null values");
    console.log("<answer>C3</answer>");
    return;
  }

  const morningAreaKm2 = morningArea / 1e6;
  const afternoonAreaKm2 = afternoonArea / 1e6;

  console.log(`Morning fog area: ${morningAreaKm2.toFixed(2)} km²`);
  console.log(`Afternoon fog area: ${afternoonAreaKm2.toFixed(2)} km²`);
  console.log(`Change: ${(morningAreaKm2 - afternoonAreaKm2).toFixed(2)} km²`);

  if (morningAreaKm2 > afternoonAreaKm2) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
